<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Exam Setup</h1><p>Connect exams, classes and assigned subjects.</p></div></header><section class="module-card"><div class="module-card__body"><form method="post" action="<?= url('/admin/exams/setup') ?>"><?= csrf_field() ?><div class="module-form-grid module-form-grid--three"><div class="module-field"><label>Exam</label><select class="module-select" name="exam" required><?php foreach($exams as$e):?><option value="<?= $e['id'] ?>"><?= e($e['name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Class</label><select class="module-select" name="class" required><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Subject</label><select class="module-select" name="subject" required><?php foreach($subjects as$s):?><option value="<?= $s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Total Marks</label><input class="module-input" type="number" min="1" step="0.01" name="total_marks" required></div></div><button class="btn btn--primary">Save Exam Setup</button></form></div></section><section class="module-card"><div class="module-card__body"><table class="data-table"><thead><tr><th>Exam</th><th>Class</th><th>Subject</th><th>Total Marks</th></tr></thead><tbody><?php foreach($setups as$s):?><tr><td><?= e($s['exam_name']) ?></td><td><?= e($s['class_name']) ?></td><td><?= e($s['subject_name']) ?></td><td><?= e($s['total_marks']) ?></td></tr><?php endforeach ?></tbody></table></div></section></div></div></main>
